# Mean-value Bochner hull for the second-moment series Z2(x1,x2,u) = sum_m N(m)^{-1/2-u} psi(m^3,1/2+x1) conj psi(m^3,1/2+x2).
# (L3) <=> holomorphy at (0,0,1/2+). Regions (sampled boundaries), group generated by sc, sc' (sm leads to 1/L: dead).
import numpy as np, sys
from scipy.optimize import linprog
lam=float(sys.argv[1]) if len(sys.argv)>1 else 1.5417
f=lambda x: lam/2-3*x if x<0 else (lam/2 if x<=0.5 else 0.5)
e=1e-7; pts=[]
G=np.linspace(-2.5,2.5,81)
for x1 in G:
    for x2 in G:
        pts.append((x1,x2,f(x1)+f(x2)-0.5+e))                     # R_cc'
for u in np.linspace(-3,3,121):
    for d1 in np.linspace(0,2,9):
        for d2 in np.linspace(0,2,9):
            b=0.5+max(0,-u)+e
            R=[(b+d1,b+d2,u)]                                     # R_m (and interior offsets)
            for (a1,a2,uu) in R:
                pts.append((a1,a2,uu))
                # sc^{-1} R_m: (-x1, x2, u+3x1) = (a1,a2,uu) -> x1=-a1, u = uu-3x1
                pts.append((-a1,a2,uu+3*a1))
                pts.append((a1,-a2,uu+3*a2))
                pts.append((-a1,-a2,uu+3*a1+3*a2))
P=np.array(pts)
# filter: keep points actually satisfying their region (the sc images were generated from R_m points directly)
n=len(P)
r=linprog(P[:,2],A_eq=np.vstack([np.ones(n),P[:,0],P[:,1]]),b_eq=[1,0,0],bounds=(0,None),method="highs")
idx=np.where(r.x>1e-9)[0]
print("lam=%.4f: min u at (0,0) = %.4f   [(L3) needs <= 0.5; bootstrap value lam-1/2 = %.4f]"%(lam,r.fun,lam-0.5))
for i in idx: print("   w=%.4f  point %s"%(r.x[i],np.round(P[i],4)))
